source = np.asarray(params["corners"], np.float32)
if params["order_mode"] == 1:
    source = source[[0,3,2,1]]
elif params["order_mode"] == 2:
    source = source[[0,2,1,3]]
marked = image.copy()
for i, point in enumerate(source):
    p = tuple(np.rint(point).astype(int))
    cv2.circle(marked, p, 6, (0,0,255), -1)
    cv2.putText(marked, str(i), (p[0]+8,p[1]), cv2.FONT_HERSHEY_SIMPLEX, .7, (0,0,255), 2)

kept = []
for index, area in enumerate(areas):
    if area >= params["min_area"]:
        kept.append(index)
selected = np.asarray(kept, dtype=np.int32).reshape(-1, 1)

centers = []
for contour in contours:
    moments = cv2.moments(contour)
    if moments["m00"] != 0:
        centers.append([moments["m10"] / moments["m00"], moments["m01"] / moments["m00"], cv2.contourArea(contour)])
center_table = np.asarray(centers, dtype=np.float64).reshape(-1, 3)

annotated = outlined.copy()
for contour in contours:
    epsilon = params["epsilon_milli"] / 1000 * cv2.arcLength(contour, True)
    polygon = cv2.approxPolyDP(contour, epsilon, True)
    for point in polygon.reshape(-1, 2):
        cv2.circle(annotated, tuple(point), 5, (0, 220, 255), -1)
for cx, cy, area in centers:
    cv2.drawMarker(annotated, (round(cx), round(cy)), (255, 0, 0), cv2.MARKER_CROSS, 18, 2)

frames = np.asarray(params["frames"], dtype=np.float64)
observed = image.copy()
for frame in frames:
    for x, y in frame:
        cv2.circle(observed, (round(x), round(y)), 3, (0, 100, 220), -1)

stabilized = observed.copy()
for x, y in median_centers:
    cv2.drawMarker(stabilized, (round(x), round(y)), (0, 170, 0), cv2.MARKER_CROSS, 18, 2)
for x, y in mean_centers:
    cv2.circle(stabilized, (round(x), round(y)), 8, (200, 0, 0), 2)
